import {quickEntries,searchQuick} from './quick-data.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let query='',kind='전체';
export function quickPage(){const r=quickEntries.find(r=>r.id===location.hash.split('/')[1]);if(r){query=r.code;kind='전체';}return `<div class="page-heading"><div><div class="eyebrow">LOOK IT UP, GET BACK TO WORK</div><h1>필드·T-code 빠른찾기</h1><p>뜻을 확인하고, 필요한 이름만 복사하세요. 자세한 설명은 관련 노트로 이어집니다.</p></div><span class="syntax-total">${quickEntries.length}개 참조</span></div><div class="quick-search-row"><label>빠른 검색<input id="quick-search" type="search" value="${esc(query)}" placeholder="지급보류, ZTERM, FB03, 타입 오류…"></label><button class="button secondary" data-quick-reset>초기화</button></div><div class="quick-filters" role="group" aria-label="참조 종류">${['전체','필드','T-code','오류'].map(k=>`<button data-quick-kind="${k}" aria-pressed="${kind===k}">${k}</button>`).join('')}<span id="quick-count" role="status"></span></div><div id="quick-results"></div><p class="quick-footnote">필드와 T-code는 대상 SAP의 버전·설정·권한에서 확인하세요. 복사 버튼은 이름만 복사하며 SAP 명령을 실행하지 않습니다. ‘오류’에는 덤프·예외 이름과 증상 키워드가 함께 포함됩니다.</p>`;}
export function renderQuick(){const root=document.querySelector('#quick-results');if(!root)return;const items=searchQuick(query).filter(r=>kind==='전체'||r.kind===kind);document.querySelector('#quick-count').textContent=`${items.length}개`;document.querySelectorAll('[data-quick-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.quickKind===kind)));root.innerHTML=items.length?`<div class="quick-table"><table><thead><tr><th>이름</th><th>뜻·사용 위치</th><th>종류</th><th>바로 사용</th></tr></thead><tbody>${items.map(r=>`<tr id="quick-${r.id}"><td><code>${esc(r.code)}</code><strong>${esc(r.title)}</strong></td><td>${esc(r.description)}</td><td><span class="tag">${esc(r.kind)}</span></td><td><div><button data-quick-copy="${r.id}" aria-label="${esc(r.code)} 이름 복사">이름 복사</button>${r.document?`<button data-quick-document="${r.document}">원문 작업 순서 ↗</button>`:`<button data-note-open="${r.note}">관련 노트 ↗</button>`}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="notes-empty"><h2>맞는 참조가 없어요.</h2><p>짧은 코드나 한국어 뜻으로 다시 검색해보세요.</p><button class="button secondary" data-quick-reset>전체 보기</button></div>';}
export function bindQuick({navigate,copy}){document.addEventListener('input',e=>{if(e.target.id==='quick-search'){query=e.target.value;renderQuick();}});document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.quickDocument){navigate('docs',b.dataset.quickDocument);return;}if(b.dataset.quickOpen){navigate('quick',b.dataset.quickOpen);return;}if(b.dataset.quickKind){kind=b.dataset.quickKind;renderQuick();return;}if(b.hasAttribute('data-quick-reset')){query='';kind='전체';const input=document.querySelector('#quick-search');if(input)input.value='';renderQuick();return;}if(b.dataset.quickCopy){const r=quickEntries.find(r=>r.id===b.dataset.quickCopy);if(r)await copy(r.code,r.title+' · 참조');}});}
